#include <bits/stdc++.h>
using namespace std;using ll=long long;const ll INF=(1LL<<62);struct Line{ll m=0,b=INF;ll at(ll x)const{return m*x+b;}};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;vector<ll>x(n),m(n),fee(n),coords;for(ll&v:x)cin>>v;for(ll&v:m)cin>>v;for(ll&v:fee)cin>>v;coords=x;sort(coords.begin(),coords.end());coords.erase(unique(coords.begin(),coords.end()),coords.end());vector<Line>tree(4*coords.size());auto add=[&](auto&&self,Line nw,int p,int l,int r)->void{int mid=(l+r)/2;if(tree[p].at(coords[mid])>nw.at(coords[mid]))swap(tree[p],nw);if(l==r)return;if(tree[p].at(coords[l])>nw.at(coords[l]))self(self,nw,p*2,l,mid);else if(tree[p].at(coords[r])>nw.at(coords[r]))self(self,nw,p*2+1,mid+1,r);};auto get=[&](auto&&self,int p,int l,int r,int at)->ll{ll ans=tree[p].at(coords[at]);if(l==r)return ans;int mid=(l+r)/2;return min(ans,at<=mid?self(self,p*2,l,mid,at):self(self,p*2+1,mid+1,r,at));};vector<ll>dp(n);add(add,{m[0],0},1,0,coords.size()-1);for(int i=1;i<n;i++){int at=lower_bound(coords.begin(),coords.end(),x[i])-coords.begin();dp[i]=fee[i]+get(get,1,0,coords.size()-1,at);add(add,{m[i],dp[i]},1,0,coords.size()-1);}cout<<dp[n-1]<<'\n';}
